<script setup lang="ts">
import {ref,shallowRef,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import M9Sidebar from '../components/M9Sidebar.vue'
import {accountSettingsTarget} from '../services/accountSettings'
import {tmdbRequest,tmdbChanged,tmdbErrors} from '../services/tmdb'
import {createFeedbackBoard,vFeedback} from '../services/recommendationFeedback'
const route=useRoute(),router=useRouter(),expanded=ref(localStorage.getItem('mi2_nav_expanded')==='true')
const channels=ref<any[]>([]),data=ref<any>(null),genres=ref<any[]>([]),loading=ref(true),error=ref(''),failed=ref<Record<string,boolean>>({})
const tmdbBusy=ref(false),tmdbNotice=ref('')
const keyword=ref(''),genre=ref(''),yearFrom=ref(''),yearTo=ref(''),runtime=ref(''),minVotes=ref(''),localOnly=ref(false),unwatched=ref(false)
const channel=computed(()=>String(route.query.channel||'daily'))
const selected=computed(()=>channels.value.find(c=>c.id===channel.value))
let controller:AbortController|undefined,sequence=0
const feedback=shallowRef<ReturnType<typeof createFeedbackBoard>>()
async function get(path:string,signal?:AbortSignal){const r=await fetch('/api/catalog/'+path,{credentials:'same-origin',signal});const body=await r.json();if(!r.ok)throw new Error(r.status===401?'登录已失效，请重新登录。':r.status===400?'筛选条件有误，请检查年份和范围。':'推荐频道暂时无法读取，请重试。');return body.data}
function sync(){const q=route.query;keyword.value=String(q.keyword||'');genre.value=String(q.genre||'');yearFrom.value=String(q.year_from||'');yearTo.value=String(q.year_to||'');runtime.value=String(q.runtime_max||'');minVotes.value=String(q.min_votes||'');localOnly.value=q.scope==='local';unwatched.value=q.unwatched==='true'}
async function load(){sync();controller?.abort();controller=new AbortController();const id=++sequence;loading.value=true;error.value='';data.value=null;feedback.value?.dispose()
 try{const params=new URLSearchParams({channel:channel.value,limit:'36'});for(const key of ['keyword','genre','year_from','year_to','runtime_max','min_votes','scope','unwatched'])if(route.query[key])params.set(key,String(route.query[key]));const result=await get('recommendations?'+params,controller.signal);if(id===sequence){data.value=result;feedback.value=createFeedbackBoard({channel:channel.value,period:result.period,context:'recommendations',items:result.items})}}
 catch(e){if(id===sequence&&!controller.signal.aborted)error.value=(e as Error).message}finally{if(id===sequence)loading.value=false}}
async function updateTMDB(){
 if(tmdbBusy.value||loading.value)return
 tmdbBusy.value=true;tmdbNotice.value=''
 try{
  const publicBoard=!!selected.value?.public,ids=publicBoard?[]:(data.value?.items||[]).filter((m:any)=>m.in_catalog&&m.tmdb_id).slice(0,data.value?.tmdb_connection?.max_detail_refresh||6).map((m:any)=>m.movie_id)
  if(!publicBoard&&!ids.length){tmdbNotice.value='当前片单没有可匹配 TMDB 的影片。';return}
  const r=await tmdbRequest('refresh','POST',publicBoard?{channel:channel.value}:{movie_ids:ids});const ok=r.results.filter((x:any)=>x.status==='OK').length
  tmdbNotice.value=r.all_updated?(publicBoard?'已取得可用官方榜单；短时间内复用最新缓存。':'已更新前 '+ok+' 部影片的公开资料；个人片单顺序保持稳定。'):'部分更新失败，保留已有缓存。'+r.results.filter((x:any)=>x.status!=='OK').map((x:any)=>tmdbErrors['TMDB_'+x.status]||'上游暂不可用').join(' ')
  await load();tmdbChanged()
 }catch(e){tmdbNotice.value=(e as Error).message}finally{tmdbBusy.value=false}
}
function change(id:string){router.push({path:'/recommendations',query:{...route.query,channel:id}})}
function filter(){const query:Record<string,string>={channel:channel.value};for(const [key,value] of Object.entries({keyword:keyword.value.trim(),genre:genre.value,year_from:yearFrom.value,year_to:yearTo.value,runtime_max:runtime.value,min_votes:minVotes.value,scope:localOnly.value?'local':'',unwatched:unwatched.value?'true':''}))if(value)query[key]=value;const target={path:'/recommendations',query};if(router.resolve(target).fullPath===route.fullPath)load();else router.push(target)}
function detail(movie:any){feedback.value?.click((data.value?.items?.indexOf(movie)??-1)+1);router.push({path:'/movies',query:{...route.query,from:'recommendations'},hash:'#movie/'+movie.movie_id})}
function stamp(value?:string){if(!value)return '未提供';const d=new Date(value);return Number.isNaN(d.getTime())?'未提供':d.toLocaleString('zh-CN',{hour12:false})}
function money(value:number){return new Intl.NumberFormat('zh-CN',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value)}
const onBehavior=()=>load()
onMounted(async()=>{try{const [c,g]=await Promise.all([get('recommendation-channels'),get('genres')]);channels.value=c.items;genres.value=g.items;await load()}catch(e){error.value=(e as Error).message;loading.value=false}window.addEventListener('mi2-behavior-changed',onBehavior);window.addEventListener('mi2-tmdb-status',onBehavior)})
watch(()=>route.fullPath,()=>{if(channels.value.length)load()})
onBeforeUnmount(()=>{feedback.value?.dispose();controller?.abort();window.removeEventListener('mi2-behavior-changed',onBehavior);window.removeEventListener('mi2-tmdb-status',onBehavior)})
</script>
<template>
 <div class="recommend-shell" :style="{'--nav-width':expanded?'280px':'52.5px'}"><M9Sidebar @expanded-change="expanded=$event"/>
 <main class="recommend-main"><header><div><h1>发现下一部好电影</h1><p>从热门话题到个人片单，找到此刻想看的故事。</p></div><router-link to="/home">返回影院首页</router-link></header>
 <nav class="channel-nav" aria-label="推荐频道"><button v-for="c in channels" :key="c.id" :aria-pressed="channel===c.id" :class="{active:channel===c.id}" @click="change(c.id)">{{c.title}}</button></nav>
 <section class="board-heading"><h2>{{selected?.title||'推荐频道'}}</h2><p>{{selected?.description}}</p></section>
 <div class="tmdb-toolbar"><span>{{data?.tmdb_connection?.last_error?'TMDB 在线读取未成功 · 使用缓存':data?.tmdb_connection?.configured&&!data?.tmdb_connection?.enabled?'TMDB 连接已停用 · 使用缓存':data?.tmdb_connection?.enabled?'TMDB 在线连接已启用 · 按需获取':'TMDB 未连接 · 使用现有缓存'}}</span><router-link :to="accountSettingsTarget('tmdb',route.fullPath)">TMDB 数据连接设置</router-link><button v-if="data?.tmdb_connection?.enabled" :disabled="tmdbBusy||loading" @click="updateTMDB">{{tmdbBusy?'正在更新…':selected?.public?'立即更新此热榜':'更新前 '+(data?.tmdb_connection?.max_detail_refresh||6)+' 部影片资料'}}</button></div><p v-if="tmdbNotice" role="status" class="notice">{{tmdbNotice}}</p>
 <form class="filters" @submit.prevent="filter">
  <label>电影名称<input v-model="keyword" maxlength="100" placeholder="搜索当前频道"/></label>
  <label>类型<select v-model="genre"><option value="">全部类型</option><option v-for="g in genres" :key="g.genre_id" :value="g.name_zh">{{g.name_zh}}</option></select></label>
  <label>起始年份<input v-model="yearFrom" type="number" min="1880" max="2100" placeholder="不限"/></label>
  <label>截止年份<input v-model="yearTo" type="number" min="1880" max="2100" placeholder="不限"/></label>
  <label>最长时长<select v-model="runtime"><option value="">不限</option><option value="90">90 分钟</option><option value="120">120 分钟</option><option value="150">150 分钟</option><option value="180">180 分钟</option></select></label>
  <label>最低票数<input v-model="minVotes" type="number" min="1" max="10000000" :placeholder="channel==='top_rated'?'默认100票':'不限'"/></label>
  <label class="check" v-if="selected?.public"><input type="checkbox" v-model="localOnly"/>只看已入库</label>
  <label class="check"><input type="checkbox" v-model="unwatched"/>排除已看</label><button class="apply" type="submit">应用筛选</button><router-link :to="{path:'/recommendations',query:{channel}}">重置</router-link>
 </form>
 <div v-if="loading" class="state" role="status">正在读取推荐与个人状态…</div>
 <div v-else-if="error" class="state" role="alert"><p>{{error}}</p><button @click="load">重试</button><router-link to="/login">重新登录</router-link></div>
 <template v-else-if="data"><div class="provenance"><span>{{selected?.public?'官方榜单采集':'库内资料更新'}}：{{stamp(data.source_as_of)}}</span><span v-if="data.period">片单周期：{{data.period}} · 北京时间</span><span>{{data.candidate_count||0}} 部符合条件 · 零模型调用</span><button @click="load">重新读取</button></div>
 <p v-if="data.status==='STALE'" class="notice" role="status">当前为缓存榜单，请以采集时间为准。</p><p v-for="note in data.limitations" :key="note" class="notice">{{note}}</p>
 <div v-if="!data.items.length" class="state"><h3>{{data.status==='UNAVAILABLE'?'官方榜单尚未就绪':'暂无符合条件的电影'}}</h3><p>可以减少筛选条件；个人频道需要相应的收藏、评分或想看记录。</p><router-link to="/movies">浏览电影并完善偏好</router-link></div>
 <div v-else class="poster-grid"><article v-for="(movie,index) in data.items" :key="sequence+':'+movie.key" v-feedback="{board:feedback,position:Number(index)+1}" class="movie-card" :data-movie-id="movie.movie_id||''">
  <button v-if="movie.in_catalog" class="board-poster" :aria-label="'查看《'+movie.title+'》详情'" @click="detail(movie)"><img v-if="movie.poster&&!failed[movie.key]" :src="movie.poster" :alt="movie.title+'海报'" loading="lazy" @error="failed[movie.key]=true"/><span v-else class="fallback">{{movie.title}}<small>暂无可用海报</small></span><span class="rank">{{movie.source_rank?'#'+movie.source_rank:movie.rank}}</span></button>
  <a v-else class="board-poster" @click="feedback?.click(Number(index)+1)" :href="movie.tmdb_url" target="_blank" rel="noopener noreferrer" :aria-label="'在 TMDB 查看《'+movie.title+'》（新标签页）'"><img v-if="movie.poster&&!failed[movie.key]" :src="movie.poster" :alt="movie.title+'海报'" loading="lazy" @error="failed[movie.key]=true"/><span v-else class="fallback">{{movie.title}}<small>暂无可用海报</small></span><span class="rank">#{{movie.source_rank}}</span><span class="external">库外影片 · TMDB</span></a>
  <h3>{{movie.title}}</h3><p class="meta">{{movie.release_year||'年份未提供'}}<template v-if="movie.runtime_minutes"> · {{movie.runtime_minutes}} 分钟</template></p><p class="genre">{{movie.genres?.join(' / ')||'类型未提供'}}</p>
  <p v-if="channel==='revenue'" class="metric">累计 {{money(movie.revenue)}}<small v-if="movie.revenue_as_of" class="meta"> · 资料 {{new Date(movie.revenue_as_of).toLocaleDateString('zh-CN')}}</small></p><p v-else-if="movie.tmdb_rating!=null" class="metric">TMDB {{movie.tmdb_rating.toFixed(1)}}<span> · {{movie.vote_count.toLocaleString()}} 票</span></p>
  <p v-if="selected?.public&&movie.tmdb_popularity!=null" class="meta">热度 {{movie.tmdb_popularity.toFixed(1)}}</p><p class="reason">{{movie.reasons?.join('；')}}</p>
 </article></div></template>
 </main></div>
</template>
<style scoped>
.tmdb-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px 22px;margin:18px 0 24px;color:#c3b4d3;font-size:12px}.tmdb-toolbar button{background:#241a32;border:1px solid #705486;padding:8px 12px;border-radius:6px;color:#e7d4ff;cursor:pointer}.tmdb-toolbar button:disabled{opacity:.5;cursor:not-allowed}.recommend-shell{min-height:100vh;background:#0b0c10;color:#f1edf8;--muted:#b8acc8;font-family:Inter,"Microsoft YaHei",sans-serif}.recommend-main{margin-left:var(--nav-width);padding:36px clamp(22px,3.6vw,64px) 64px;transition:margin-left .25s;min-width:0}.recommend-main *{box-sizing:border-box}.recommend-main a{color:#cdb4f2;text-underline-offset:4px}.recommend-main button,.recommend-main input,.recommend-main select{font:inherit;color:inherit}.recommend-main button{cursor:pointer}.recommend-main :focus-visible{outline:2px solid #ccaff6;outline-offset:4px}.recommend-main ::selection{background:#c6a3ec;color:#181020}header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:28px}h1{font-size:30px;letter-spacing:-.02em;margin:0 0 12px}header p,.board-heading p{color:var(--muted);font-size:14px;line-height:1.8;margin:0}.channel-nav{display:flex;flex-wrap:wrap;gap:8px;padding-bottom:24px;border-bottom:1px solid #ffffff18}.channel-nav button{background:transparent;border:1px solid #746086;border-radius:7px;padding:10px 16px;font-size:14px}.channel-nav button:hover{background:#241c31}.channel-nav button.active{background:#bda1e0;border-color:#bda1e0;color:#170f24;font-weight:700}.board-heading{margin:27px 0 22px}.board-heading h2{font-size:22px;margin:0 0 8px}.filters{display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;padding-bottom:24px}.filters label{display:flex;flex-direction:column;gap:7px;color:var(--muted);font-size:12px}.filters input,.filters select{height:38px;background:#17131f;border:1px solid #6d5e7e;border-radius:5px;padding:6px 10px;max-width:160px;color:#eee8f6}.filters input[type=number]{width:112px}.filters .check{flex-direction:row;align-items:center;min-height:38px}.filters input[type=checkbox]{accent-color:#bda1e0;width:16px;height:16px;margin:0}.apply,.state button{padding:9px 18px;background:#bda1e0;color:#170f24!important;border:0;border-radius:5px;font-weight:700}.apply:hover,.state button:hover{background:#d4baf5}.filters>a{font-size:13px;line-height:38px}.provenance{display:flex;flex-wrap:wrap;gap:10px 24px;color:var(--muted);font-size:12px;align-items:center;margin:4px 0 12px}.provenance button{background:none;border:0;color:#d4b9fa;text-decoration:underline;text-underline-offset:3px;padding:0}.notice{font-size:12px;line-height:1.7;color:#c6b5d8;margin:6px 0}.poster-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:30px 22px;margin-top:24px}.movie-card{min-width:0}.board-poster{display:block;width:100%;aspect-ratio:2/3;position:relative;overflow:hidden;background:#201b2c;border:0;border-radius:9px;padding:0;color:#e4d8f1;transition:transform .18s}.board-poster:hover{transform:translateY(-4px)}.board-poster img{width:100%;height:100%;object-fit:cover;display:block}.rank{position:absolute;top:9px;left:9px;background:#100b1bdc;color:#fff;padding:5px 9px;border-radius:4px;font-size:14px;font-variant-numeric:tabular-nums}.external{position:absolute;bottom:0;inset-inline:0;background:#1d122dec;color:#ead9ff;padding:9px 8px;font-size:12px;text-align:center}.fallback{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;text-align:center;gap:12px;line-height:1.7}.fallback small{color:#bcaacb}.movie-card h3{font-size:15px;line-height:1.5;margin:12px 0 5px}.meta,.genre{font-size:12px;color:var(--muted);line-height:1.7;margin:3px 0}.metric{color:#e2c495;font-size:14px;margin:9px 0 5px;font-variant-numeric:tabular-nums}.metric span{color:var(--muted);font-size:11px}.reason{font-size:12px;line-height:1.7;color:#c6b5db;margin:6px 0}.state{padding:60px 0;color:var(--muted);line-height:1.8;min-height:240px}.state button{margin-right:18px}@media(min-width:2000px){.poster-grid{grid-template-columns:repeat(auto-fill,minmax(190px,1fr))}}@media(max-width:700px){header{align-items:flex-start;flex-direction:column;gap:10px}h1{font-size:25px}.recommend-main{padding:24px 18px 60px}.poster-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 14px}.channel-nav button{padding:9px 11px;font-size:12px}}@media(prefers-reduced-motion:reduce){.recommend-main,.board-poster{transition:none}}
</style>
